        entry.nodes.push_back(node);
        buffer_.push_back(std::move(entry));
    }

    void Send(ConsoleMessageLevel level, const std::string& message, const std::vector<WebNode>& nodes) {
        LogEntry entry;
        entry.message = message;
        entry.nodes = nodes;
        buffer_.push_back(std::move(entry));
    }

    void Flush() {
        for (auto& entry : buffer_) {
            std::string formattedMessage = FormatMessage(entry.message, entry.nodes);
            frame_.AddConsoleMessage(formattedMessage, level);
        }
        buffer_.clear();
    }

private:
    std::string FormatMessage(const std::string& message, const std::vector<WebNode>& nodes) {
        std::string result = message;
        for (const auto& node : nodes) {
            // Example logic to remove sensitive info
            if (node.HasAttribute("type") && node.Attribute("type") == "password") {
                result += " [REDACTED]";
            } else {
                result += " " + node.TextContent();
            }
        }
        return result;
    }

    WebLocalFrame& frame_;
    std::vector<LogEntry> buffer_;
};

