typedef struct PageFormAnalyserLogger {
    WebLocalFrame* frame;
    LogEntry* buffer;
    int buffer_size;
} PageFormAnalyserLogger;

// Constructor
PageFormAnalyserLogger* create_PageFormAnalyserLogger(WebLocalFrame* frame) {
    PageFormAnalyserLogger* logger = (PageFormAnalyserLogger*)malloc(sizeof(PageFormAnalyserLogger));
    if (!logger) return NULL;

    logger->frame = frame;
    logger->buffer = NULL;
    logger->buffer_size = 0;

    return logger;
}

// Destructor
void destroy_PageFormAnalyserLogger(PageFormAnalyserLogger* logger) {
    if (!logger) return;

    // Clean up buffer
    for (int i = 0; i < logger->buffer_size; ++i) {
        free(logger->buffer[i].message);
        free(logger->buffer[i].nodes);
    }

    free(logger->buffer);
    free(logger);
}

// Send method to log messages
void Send(PageFormAnalyserLogger* logger, const char* message, const char* console_level, const char* node) {
    if (!logger || !message || !console_level) return;

    // Create a new log entry
    LogEntry entry;
    entry.message = strdup(message);
    entry.nodes = strdup(node);

    // Add the entry to the buffer
    LogEntry* new_buffer = (LogEntry*)realloc(logger->buffer, sizeof(LogEntry) * (logger->buffer_size + 1));
    if (!new_buffer) return;

    new_buffer[logger->buffer_size] = entry;
    logger->buffer = new_buffer;
    logger->buffer_size++;
}

// Flush method to process and send the log messages
void Flush(PageFormAnalyserLogger* logger) {
    if (!logger || logger->buffer_size == 0) return;

    for (int i = 0; i < logger->buffer_size; ++i) {
        LogEntry* entry = &logger->buffer[i];

        // Filter out sensitive information (e.g., password fields)
        char* filtered_message = entry->message;

        // Example: Remove password values from the message
        char* password_pattern = "password=";
        char* password_start = strstr(filtered_message, password_pattern);
        if (password_start) {
            char* password_end = password_start + strlen(password_pattern);
            char* rest = password_end;
            while (*rest && *rest != '&') {
                rest++;
            }
            size_t length = rest - password_start;
            for (char* c = password_start; c < rest; ++c) {
                *c = '*';
            }
        }

        // Construct and send the message to the console
        printf("Console [%s]: %s\n", console_level, filtered_message);
    }

    // Clear the buffer
    logger->buffer_size = 0;
